import React,{useState,useEffect,useRef,createContext,useContext} from 'react';
import {createRoot} from 'react-dom/client';
import {BrowserRouter,Routes,Route,NavLink,Link,useNavigate,useLocation} from 'react-router-dom';
import {HardHat,ArrowUpRight,ArrowRight,ArrowLeft,Wallet,MapPin,Route as RouteIcon,ShieldCheck,BookOpen,Home as HomeIcon,Mic,Volume2,Square,Globe,Menu,X,Activity,Check,Info,Building2,Phone,FileCheck,HeartPulse,ChevronDown,Download,RefreshCw,Search,CheckCircle2,AlertCircle,ExternalLink,Compass,Languages,TrendingUp,Clock,LockKeyhole} from 'lucide-react';
import {claimPlayback,releasePlayback,stopAllPlayback,selectVoice} from './speechPlayback';
import SaathiDrawing from './components/Saathi';
import AnimatedMoney from './components/AnimatedMoney';
import CityArt from './components/CityArt';
import CityIllustration from './components/CityIllustration';
import RouteMap from './components/RouteMap';
import {api,logSearch,money,downloadJSON} from './api';
import './styles.css';
import {normalizeDigits} from '../../lib/parser.js';
import {languages,languageInfo,translate,formatMessage} from '../../lib/i18n.js';
const Lang=createContext();const useLang=()=>useContext(Lang);
function Saathi(props){const {t}=useLang();return <SaathiDrawing {...props} label={t('Your companion')}/>;}
const cities=['Delhi','Gurgaon','Noida','Chennai','Mumbai'];
const journeyCities=['Patna','Noida','Chennai','Delhi','Gurgaon','Mumbai'];

const labels={unskilled:['Helper / unskilled','हेल्पर / अकुशल'],semi_skilled:['Semi-skilled worker','अर्ध कुशल कामगार'],skilled:['Mason / skilled worker','राजमिस्त्री / कुशल कामगार']};
const nav=[['/','Home','होम',HomeIcon],['/predict','Wage outlook','मजदूरी अनुमान',Wallet],['/opportunities','Compare cities','शहरों की तुलना',Compass],['/route','Plan your route','यात्रा की योजना',RouteIcon],['/guide','City essentials','शहर की ज़रूरी जानकारी',BookOpen],['/check','Check your pay','मजदूरी जाँचें',ShieldCheck],['/escalate','Get Help','मदद लें',HeartPulse]];
function Button({children,secondary=false,className='',...props}){return <button className={`${secondary?'btn-glass':'btn-primary'} ${className}`} {...props}>{children}</button>;}
function Tag({children,tone=''}){return <span className={`tag ${tone}`}>{children}</span>;}
function Note({children}){return <div className="note"><Info size={16}/><div>{children}</div></div>;}
function Source({source}){const {t}=useLang();return <details className="source"><summary><Info size={14}/>{t('View source & assumptions','स्रोत और मान्यताएँ देखें')}<ChevronDown size={14}/></summary><div><p>{t(source.verification_note)}</p>{source.last_verified&&<p>{t('Date checked')}: {source.last_verified}</p>}<p>{t('Effective period in supplied plan:','दी गई योजना की प्रभावी अवधि:')} {t(source.effective_date)}</p><a href={source.source_url} target="_blank" rel="noreferrer">{t('Open official department portal','आधिकारिक विभाग की वेबसाइट खोलें')} <ExternalLink size={13}/></a><p>{t('Portal link is not evidence that this rate is current. Verify the exact notification and employment schedule.','वेबसाइट लिंक इस दर के वर्तमान होने का प्रमाण नहीं है। लागू अधिसूचना और कार्य श्रेणी की जाँच करें।')}</p></div></details>;}
function Speak({text,locale}){
 const {t,language,locale:activeLocale}=useLang();
 const [speaking,setSpeaking]=useState(false),[loading,setLoading]=useState(false),[error,setError]=useState(''),[audioSrc,setAudioSrc]=useState('');
 const audio=useRef(),utterance=useRef(),request=useRef(),url=useRef(),generation=useRef(0),stop=useRef();
 if(!stop.current)stop.current=()=>{generation.current++;if(utterance.current){window.speechSynthesis?.cancel();utterance.current=null;}request.current?.abort();request.current=null;audio.current?.pause();if(audio.current){audio.current.removeAttribute('src');audio.current.load();}if(url.current)URL.revokeObjectURL(url.current);url.current=null;setAudioSrc('');setSpeaking(false);setLoading(false);releasePlayback(stop.current);};
 useEffect(()=>{stop.current();setError('');return()=>stop.current();},[language,locale,text]);
 const play=async()=>{
  if(speaking){stopAllPlayback();return;}
  if(url.current&&audio.current?.paused){claimPlayback(stop.current);setError('');audio.current.currentTime=0;try{await audio.current.play();}catch{setError(t('Tap Listen to Saathi again to start audio.'));}return;}
  stop.current();claimPlayback(stop.current);setError('');
  const target=locale||activeLocale,code=target.toLowerCase().split('-')[0],token=generation.current;
  const synth=window.speechSynthesis;
  let voices=synth?.getVoices()||[];
  if(synth&&!voices.length){setSpeaking(true);setLoading(true);voices=await new Promise(resolve=>{const finish=()=>{clearTimeout(timer);synth.removeEventListener('voiceschanged',ready);resolve(synth.getVoices());};const ready=()=>{if(selectVoice(synth.getVoices(),target))finish();};const timer=setTimeout(finish,1000);synth.addEventListener('voiceschanged',ready);});if(token!==generation.current)return;setLoading(false);}
  const voice=selectVoice(voices,target);
  if(!voice&&['ml','or','od','ori'].includes(code)){
   setSpeaking(true);setLoading(true);request.current=new AbortController();
   try{
    const response=await fetch('/api/speech',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text,language:target}),signal:request.current.signal});
    if(!response.ok)throw new Error('Speech request failed');
    const blob=await response.blob();if(token!==generation.current)return;
    const source=URL.createObjectURL(blob);url.current=source;setAudioSrc(source);audio.current.src=source;audio.current.load();setLoading(false);
    try{await audio.current.play();}catch(e){if(token!==generation.current)return;setSpeaking(false);if(e.name==='NotAllowedError')setError(t('Tap Listen to Saathi again to start audio.'));else throw e;}
   }catch(e){if(token!==generation.current||e.name==='AbortError')return;stop.current();setError(t('Voice playback failed. You can read the text below.'));}
   return;
  }
  if(!synth){releasePlayback(stop.current);setError(t('Read-aloud is unavailable in this browser.'));return;}
  if(!voice){setSpeaking(false);releasePlayback(stop.current);setError(t('A voice for this language is not installed in this browser. Read the displayed text or install a matching voice.'));return;}
  const utter=new SpeechSynthesisUtterance(text);utterance.current=utter;utter.voice=voice;utter.lang=target;utter.rate=.9;
  utter.onend=()=>{if(token===generation.current){utterance.current=null;setSpeaking(false);releasePlayback(stop.current);}};
  utter.onerror=e=>{if(token!==generation.current)return;utterance.current=null;setSpeaking(false);releasePlayback(stop.current);if(!['canceled','interrupted'].includes(e.error))setError(t('Voice playback failed. You can read the text below.'));};
  setSpeaking(true);synth.speak(utter);
 };
 return <><Button secondary onClick={play} className="compact" aria-busy={loading}>{speaking?<Square size={15}/>:<Volume2 size={16}/>} {speaking?t('Stop'):t('Listen to Saathi')}</Button>{loading&&<div role="status" className="muted small"><Skeleton/>{t('Reading…')}</div>}<audio ref={audio} hidden preload="auto" className="saathi-audio" aria-label={t('Listen to Saathi')} data-speech-language={locale||activeLocale} onPlay={()=>{claimPlayback(stop.current);setSpeaking(true);setError('');}} onPause={()=>setSpeaking(false)} onEnded={()=>{setSpeaking(false);releasePlayback(stop.current);}} onError={()=>{if(url.current){setSpeaking(false);setError(t('Voice playback failed. You can read the text below.'));}}}/>{error&&<p role="status" className="muted">{error}</p>}</>;
}
function VoiceInput({value,onChange,onParse,busy}){const {hi,t,language,locale:activeLocale,message}=useLang();const [listening,setListening]=useState(false),[status,setStatus]=useState('');const recognition=useRef(),micTimer=useRef();useEffect(()=>()=>{clearTimeout(micTimer.current);recognition.current?.abort();},[]);
 const start=()=>{if(listening){clearTimeout(micTimer.current);recognition.current?.abort();setListening(false);setStatus(t('Recording stopped. You can type below.','रिकॉर्डिंग रोक दी। नीचे लिख सकते हैं।'));return;}const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){setStatus(t('Voice input is unavailable here. Type your statement below.','यहाँ आवाज़ से इनपुट उपलब्ध नहीं है। नीचे लिखें।'));return;}try{const r=new SR();recognition.current=r;r.lang=activeLocale;r.interimResults=false;r.onstart=()=>{clearTimeout(micTimer.current);setListening(true);setStatus(t('Listening… speak about your city, job and pay.','सुन रहा हूँ… शहर, काम और मजदूरी बताइए।'));};r.onresult=e=>{clearTimeout(micTimer.current);onChange(e.results[0][0].transcript);setStatus(t('Transcript ready. Review it, then fill the form.','बात लिख ली गई। जाँचकर फ़ॉर्म भरें।'));};r.onerror=e=>{clearTimeout(micTimer.current);setStatus(t('Microphone unavailable or permission denied. You can type below.','माइक उपलब्ध नहीं है या अनुमति नहीं मिली। नीचे लिख सकते हैं।'));setListening(false);};r.onend=()=>{clearTimeout(micTimer.current);setListening(false);};setListening(true);setStatus(t('Requesting microphone access… You can still type below.','माइक की अनुमति माँगी जा रही है… नीचे लिख सकते हैं।'));r.start();micTimer.current=setTimeout(()=>{r.abort();setListening(false);setStatus(t('Voice input did not start. Use typed input or try a supported browser.','आवाज़ से इनपुट शुरू नहीं हुआ। लिखें या समर्थित ब्राउज़र में प्रयास करें।'));},10000);}catch{clearTimeout(micTimer.current);setListening(false);setStatus(t('Could not start voice input. Type below.','आवाज़ शुरू नहीं हुई। नीचे लिखें।'));}};
 return <div className="voice-box"><div className="row-between"><div><strong>{t('Tell Saathi in your own words','साथी को अपने शब्दों में बताइए')}</strong><p className="muted small">{t('Speak or type. You can edit every detail.','बोलें या लिखें। हर जानकारी बदल सकते हैं।')}</p></div><button className={`mic ${listening?'listening':''}`} onClick={start} type="button" aria-label={listening?t('Stop recording','रिकॉर्डिंग रोकें'):t('Start voice input','आवाज़ से बताएँ')}>{listening?<Square size={20}/>:<Mic size={20}/>}</button></div><textarea aria-label={t('Your statement','आपका बयान')} value={value} onChange={e=>onChange(e.target.value)} placeholder={t('I am a helper in Noida. I earn 400 rupees per day.','मैं नोएडा में हेल्पर हूँ। मुझे रोज 400 रुपये मिलते हैं।')} rows={3}/><div className="row-between"><span className="muted small">{t('Typed input is always available','लिखकर बताने की सुविधा हमेशा उपलब्ध है')}</span><Button secondary className="compact" type="button" onClick={onParse} disabled={!value.trim()||busy}>{busy?t('Reading…','पढ़ रहा हूँ…'):t('Fill my form','मेरा फ़ॉर्म भरें')}<ArrowRight size={15}/></Button></div>{status&&<p className="muted small" role="status">{status}</p>}</div>;
}
function CitySelect({value,onChange,label}){const {hi,t,language,locale:activeLocale,message}=useLang();return <label>{label||t('Destination city','किस शहर में काम करेंगे?')}<select required value={value} onChange={e=>onChange(e.target.value)}><option value="" disabled>{t('Choose a city','शहर चुनें')}</option>{cities.map(c=><option key={c} value={c}>{t(c)}</option>)}</select></label>;}
function JobSelect({value,onChange}){const {hi,t,language,locale:activeLocale,message}=useLang();return <label>{t('Type of work','काम की श्रेणी')}<select required value={value} onChange={e=>onChange(e.target.value)}><option value="" disabled>{t('Choose a work category','काम चुनें')}</option>{Object.entries(labels).map(([key,value])=><option value={key} key={key}>{t(value[0],value[1])}</option>)}</select></label>;}
function SceneBackdrop({city="Chennai"}){return <div className="scene-backdrop" data-city={city} aria-hidden="true"><CityArt city={city}/></div>;}
function PageHeading({eyebrow,title,description,city="Noida"}){const {t}=useLang();return <><SceneBackdrop city={city}/><div className="page-heading" data-city={city}><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{description}</p><CityIllustration city={city} label={t(city)} className="heading-illustration"/></div></>;}
function Skeleton(){return <div className="skeleton" aria-hidden="true"><i className="skeleton-amount"/><div><i/><i/></div><i className="skeleton-line"/></div>;}
function Empty({message,busy=false}){const {t}=useLang();return <div className="empty" aria-busy={busy}><Saathi pose={busy?'thinking':'welcome'}/>{busy&&<Skeleton/>}<h3>{busy?t('Saathi is checking…','साथी जाँच रहा है…'):t('Let’s work it out together','आइए मिलकर जानें')}</h3><p>{message}</p></div>;}
function ErrorMessage({message}){const {t}=useLang();return message?<div role="alert" className="error"><AlertCircle size={17}/>{t(message)}</div>:null;}
function App(){const [language,setLanguage]=useState(()=>languageInfo(localStorage.getItem('saathi-language')).code);const [menu,setMenu]=useState(false);const hi=language==='hi';const locale=languageInfo(language).locale;const t=(en,hindi)=>translate(language,en,hindi);const message=(key,params)=>formatMessage(language,key,params);const location=useLocation();useEffect(()=>{document.documentElement.lang=language;document.documentElement.dir=languageInfo(language).dir;document.documentElement.dataset.language=language;document.title=translate(language,'Voice of Wagers')+' · '+translate(language,'YOUR WORK. YOUR WORTH.');localStorage.setItem('saathi-language',language);stopAllPlayback();},[language]);useEffect(()=>{setMenu(false);window.scrollTo(0,0);},[location.pathname]);return <Lang.Provider value={{hi,t,language,locale,message}}><a href="#main" className="skip">{t('Skip to content')}</a><header className="glass-header"><Link to="/" className="brand"><span className="brand-mark"><HardHat size={25}/></span><span><b>{t('Voice of Wagers')}<span className="brand-dot">.</span></b><small>{t('YOUR WORK. YOUR WORTH.','आपका श्रम। आपका सम्मान।')}</small></span></Link><nav className={`top-navigation ${menu?"open":""}`} aria-label={t("Main navigation")}>{nav.map(([url,en,hindi,Icon])=><NavLink key={url} to={url} end={url==="/"}><Icon size={16}/><span>{t(en,hindi)}</span></NavLink>)}</nav><div className="header-actions"><label className="language-switch"><Globe size={16}/><select aria-label={t('Language')} data-testid="language-select" value={language} onChange={e=>setLanguage(e.target.value)}>{languages.map(l=><option key={l.code} value={l.code} lang={l.code}>{l.native}</option>)}</select></label><a className="emergency" href="tel:112"><Phone size={14}/><span>{t('Emergency','आपातकाल')} <b>112</b></span></a><button className="menu-toggle" aria-label={t('Toggle navigation')} onClick={()=>setMenu(!menu)}>{menu?<X/>:<Menu/>}</button></div></header><div className="app-shell"><main id="main" data-page={location.pathname}><Routes><Route path="/" element={<Dashboard/>}/><Route path="/predict" element={<Prediction/>}/><Route path="/opportunities" element={<Opportunities/>}/><Route path="/route" element={<Planner/>}/><Route path="/guide" element={<Guide/>}/><Route path="/check" element={<WageCheck/>}/><Route path="/escalate" element={<Escalation/>}/><Route path="*" element={<div className="empty"><h1>{t('Page not found')}</h1><Link to="/">{t('Return home')}</Link></div>}/></Routes><footer><span>{t('Voice of Wagers')}</span><span>{t('Built for dignity. Guided by evidence.','सम्मान के लिए। प्रमाण के साथ।')}</span></footer></main></div></Lang.Provider>;}
function CityScene(){return <svg viewBox="0 0 650 340" className="city-scene" aria-hidden="true"><defs><linearGradient id="sky" x2="0" y2="1"><stop stopColor="#496044" stopOpacity=".2"/><stop offset="1" stopColor="#17221a"/></linearGradient></defs><circle cx="400" cy="150" r="123" fill="#97b285" opacity=".06"/><circle cx="400" cy="150" r="95" fill="none" stroke="#b6c7a8" strokeOpacity=".08"/><circle cx="400" cy="150" r="66" fill="none" stroke="#b6c7a8" strokeOpacity=".08"/><path d="M0 300H650" stroke="#769174" strokeOpacity=".2"/><g fill="url(#sky)" stroke="#728a68" strokeOpacity=".25"><path d="M45 300V180h62v120M115 300V146h65v154M480 300V175h68v125M555 300V121h58v179"/><path d="M200 300V132h76v168M203 130l35-45 39 45M451 300V217h26v83"/></g><g stroke="#a0b18e" strokeOpacity=".15"><path d="M58 196h34m-34 19h34m-34 19h34m35-69h37m-37 20h37m-37 20h37M565 138h38m-38 19h38m-38 19h38M215 159h44m-44 20h44m-44 20h44"/></g><path d="M322 250V56h11v194M285 66h169M305 56l28 10 66-10M405 66v54M398 120h14" fill="none" stroke="#7b936e" strokeWidth="3" strokeOpacity=".4"/><path d="M175 314q100-43 216-10t230 4" fill="none" stroke="#adc296" strokeOpacity=".2" strokeDasharray="5 7"/></svg>;}
function CityGallery(){const {t}=useLang();const [city,setCity]=useState("Chennai");return <section className="city-gallery"><div className="gallery-tabs" aria-label={t("Choose a city")}>{journeyCities.map(c=><button type="button" key={c} aria-pressed={city===c} onClick={()=>setCity(c)}>{t(c)}</button>)}</div><CityArt city={city} label={t(city)}/></section>;}
function Dashboard(){const {t}=useLang();const [city,setCity]=useState('Chennai');const actions=[['/predict',Wallet,'Wage outlook','Know what your work is worth.'],['/opportunities',Compass,'Compare cities','Compare the basics side by side. Choose what matters to you, with every caveat in view.'],['/route',RouteIcon,'Plan your route','A plan for the road ahead.'],['/guide',BookOpen,'City essentials','Know where to go and who can help.'],['/check',ShieldCheck,'Check your pay','Your hard work deserves fair pay.'],['/escalate',HeartPulse,'Get Help','You’re not on your own.']];return <><SceneBackdrop city={city}/><section className="dashboard-welcome"><div><span className="eyebrow">{t('YOUR MIGRATION COMPANION')}</span><h1>{t('NAMASTE, LET’S TAKE THE NEXT STEP')}</h1><p>{t('Know your wages. Find your city. Take your next step with someone by your side.')}</p></div><div className="dashboard-companion"><CityIllustration city={city} label={t(city)} className="dashboard-illustration"/><Saathi/><div><strong>{t('Namaste! I’m Saathi.')}</strong><Speak text={t("Namaste! I’m Saathi, your Voice of Wagers guide. Let’s understand your wages, choose your city and plan your next step together.")}/></div></div></section><div className="dashboard-facts"><div><MapPin/><span>{t('6 cities')}</span></div><div><Languages/><span>{t('11 languages')}</span></div><div><LockKeyhole/><span>{t('No personal details')}</span></div><div><Phone/><a href="tel:112">{t('Emergency')} <strong>112</strong></a></div></div><div className="dashboard-grid"><section className="panel dashboard-actions"><div className="panel-title"><Compass size={21}/><h3>{t('Your journey, made clearer.')}</h3></div><div className="dashboard-action-grid">{actions.map(([url,Icon,label,description],i)=><Link key={url} className={`dashboard-action action-${i}`} to={`${url}${['/predict','/guide','/route'].includes(url)?'?city='+city:''}`}><span className="feature-icon"><Icon size={23}/></span><div><h3>{t(label)}</h3><p>{t(description)}</p></div><ArrowRight size={17}/></Link>)}</div></section><aside className="dashboard-side"><section className="panel city-choice"><div className="panel-title"><MapPin size={21}/><h3>{t('Choose a city')}</h3></div><div className="gallery-tabs">{journeyCities.map(c=><button key={c} aria-pressed={city===c} onClick={()=>setCity(c)}>{t(c)}</button>)}</div><p>{t('Choose where you start and where you want to go.')}</p><Link to={`/route?city=${city}`} className="btn-primary full">{t('Build my journey plan')}<ArrowRight size={16}/></Link></section><section className="panel dashboard-pay"><div className="panel-title"><ShieldCheck size={21}/><h3>{t('Your hard work deserves fair pay.')}</h3></div><p>{t('Compare your pay with the supplied wage benchmark. No name. No employer details.')}</p><Link to="/check" className="btn-primary full">{t('Check my pay')}<ArrowRight size={16}/></Link></section></aside></div><div className="home-disclaimer"><Info size={14}/>{t('Transparent by design: wage benchmarks need notification verification; living costs and travel distances are planning estimates.')}</div></>;}
function useTask(){const [busy,setBusy]=useState(false),[error,setError]=useState('');const run=async fn=>{setError('');setBusy(true);try{await fn();}catch(e){setError(e.message);}finally{setBusy(false);}};return{busy,error,run};}
function Prediction(){const {t,hi,language,message}=useLang();const params=new URLSearchParams(useLocation().search);const [city,setCity]=useState(cities.includes(params.get('city'))?params.get('city'):'Noida'),[job,setJob]=useState('unskilled'),[result,setResult]=useState(null);const {busy,error,run}=useTask();const [transcript,setTranscript]=useState(''),[parseNote,setParseNote]=useState('');useEffect(()=>setParseNote(''),[language]);const invalidate=fn=>value=>{fn(value);setResult(null);};const submit=e=>{e.preventDefault();run(async()=>{const r=await api('predict-wage',{destination_city:city,job_category:job});await logSearch(r.city);setResult(r);});};const parse=()=>run(async()=>{const p=await api('parse-input',{transcript,mode:'text',language});setCity(p.state==='unclear'?'':p.state);setJob(p.job_category==='unclear'?'':p.job_category);setResult(null);setParseNote(t('Please confirm city and work category before calculating.','गणना से पहले शहर और काम की श्रेणी की पुष्टि करें।'));});return <><PageHeading city={city} eyebrow={t('01 / BEFORE YOU GO','01 / जाने से पहले')} title={t('Know what your work is worth.','अपने काम की कीमत जानें।')} description={t('Start with a wage benchmark. See what might remain after basic living costs.','मजदूरी के मानक से शुरू करें। बुनियादी खर्चों के बाद बचत का अनुमान देखें।')}/><div className="tool-grid"><section className="panel"><div className="panel-title"><Wallet size={21}/><h3>{t('Your next workplace','आपका अगला कार्यस्थल')}</h3></div><form onSubmit={submit}><CitySelect value={city} onChange={invalidate(setCity)}/><JobSelect value={job} onChange={invalidate(setJob)}/><Button disabled={busy} type="submit" className="full">{busy?t('Checking…','जाँच रहा हूँ…'):t('Show my wage outlook','मेरी मजदूरी का अनुमान दिखाएँ')}<ArrowRight size={17}/></Button></form><details className="voice-entry"><summary><Mic size={16}/>{t('OR USE YOUR VOICE')}</summary><VoiceInput value={transcript} onChange={setTranscript} onParse={parse} busy={busy}/></details>{parseNote&&<Note>{parseNote}</Note>}<ErrorMessage message={error}/>{result&&<div className="input-context"><Note>{t(result.note,'यह दिया गया मजदूरी मानक है, नौकरी का प्रस्ताव या बाज़ार वेतन नहीं। बचत में यात्रा, बिजली, स्वास्थ्य और घर भेजे पैसे शामिल नहीं हैं।')}</Note><Source source={result.source}/></div>}</section><section className={`panel result-panel ${result?'result-enter':''} ${result?.status==='underpaid'?'attention-once':''}`} aria-live="polite">{!result?<Empty busy={busy} message={t('Choose a city and your type of work. I’ll show the benchmark and estimated essentials.','शहर और काम चुनें। मैं मजदूरी का मानक और ज़रूरी खर्च का अनुमान दिखाऊँगा।')}/>:<><div className="row-between"><span className="eyebrow">{t(result.city)} / {t(labels[result.job_category][0],labels[result.job_category][1])}</span><Tag tone="amber">{t('PROVISIONAL','अस्थायी')}</Tag></div><h2>{t('Your wage outlook','आपकी मजदूरी का अनुमान')}</h2>{!result.available?<><Empty message={t('This city’s skill-specific rate is missing from the supplied data. I won’t substitute another category.','इस शहर की इस श्रेणी की दर उपलब्ध नहीं है। दूसरी श्रेणी की दर नहीं ली जाएगी।')}/></>:<><div className="big-value"><AnimatedMoney value={result.monthly}/><span> / {t('month','माह')}</span></div><p className="muted">{money(result.daily)} / {t('day · 26 working days','दिन · 26 कार्यदिवस')}</p>{result.classification_note&&<Note>{t(result.classification_note,'निर्माण के लिए एक सामान्य दर दी गई है, अलग कौशल श्रेणियाँ नहीं।')}</Note>}<div className="cost-grid"><div><span>{t('Shared rent','साझा किराया')} <Tag>{t('estimate','अनुमान')}</Tag></span><strong>{money(result.typical_rent)}</strong></div><div><span>{t('Food','भोजन')} <Tag>{t('estimate','अनुमान')}</Tag></span><strong>{money(result.typical_food)}</strong></div></div><div className="savings-box"><div><span>{t('Potential left after rent & food','किराए और भोजन के बाद संभावित बचत')}</span><Tag>{t('estimate','अनुमान')}</Tag></div><strong>{money(result.estimated_monthly_savings_range[0])}<small> / {t('month','माह')}</small></strong></div><div className="result-actions"><Speak text={message('prediction_message',{city:t(result.city),monthly:money(result.monthly),savings:money(result.estimated_monthly_savings_range[0])})}/><Link className="text-link" to={`/route?city=${result.city}`}>{t('Plan this journey','इस यात्रा की योजना बनाएँ')}<ArrowRight size={16}/></Link></div></>}</>}</section></div></>;}
function WageCheck(){const {t,language}=useLang();const [city,setCity]=useState('Noida'),[job,setJob]=useState('unskilled'),[amount,setAmount]=useState(''),[period,setPeriod]=useState('daily'),[result,setResult]=useState(null),[transcript,setTranscript]=useState(''),[parseNote,setParseNote]=useState('');const {busy,error,run}=useTask();const navigate=useNavigate();useEffect(()=>setResult(null),[language]);useEffect(()=>setParseNote(''),[language]);const invalidate=fn=>value=>{fn(value);setResult(null);};const submit=e=>{e.preventDefault();run(async()=>{if(amount==='')throw new Error(t('Enter the amount you receive.','आपको मिलने वाली मजदूरी भरें।'));const r=await api('verdict',{state:city,job_category:job,wage_amount:Number(amount),wage_period:period,language});await logSearch(r.city);setResult(r);});};const parse=()=>run(async()=>{const p=await api('parse-input',{transcript,mode:'text',language});setResult(null);setCity(p.state==='unclear'?'':p.state);setJob(p.job_category==='unclear'?'':p.job_category);setAmount(p.wage_amount==='unclear'?'':String(p.wage_amount));setPeriod(p.wage_period==='unclear'?'':p.wage_period);setParseNote(t('Review all fields. Anything unclear is left blank for you to choose.','हर जानकारी जाँचें। अस्पष्ट जानकारी खाली है; आप उसे चुनें।'));});
 return <><PageHeading city={city} eyebrow={t('05 / PROOF OF WAGE TRUTH','05 / मजदूरी की सच्चाई')} title={t('Hard work. Honest answers.','मेहनत आपकी। जवाब सच्चे।')} description={t('Compare the pay you receive with the supplied wage benchmark. Anonymous, by design.','मिल रही मजदूरी की तुलना दिए गए मानक से करें। आपकी पहचान पूछे बिना।')}/><div className="tool-grid"><section className="panel"><div className="panel-title"><ShieldCheck size={21}/><h3>{t('Tell us about your pay','अपनी मजदूरी बताइए')}</h3></div><details className="voice-entry"><summary><Mic size={16}/>{t('OR USE YOUR VOICE')}</summary><VoiceInput value={transcript} onChange={setTranscript} onParse={parse} busy={busy}/></details>{parseNote&&<Note>{parseNote}</Note>}<div className="divider"><span>{t('REVIEW YOUR DETAILS','अपनी जानकारी जाँचें')}</span></div><form onSubmit={submit}><div className="form-row"><CitySelect value={city} onChange={invalidate(setCity)} label={t('Where do you work?','कहाँ काम करते हैं?')}/><JobSelect value={job} onChange={invalidate(setJob)}/></div><div className="form-row"><label>{t('Pay received (₹)','मिली मजदूरी (₹)')}<input type="text" inputMode="decimal" pattern="[0-9]+([.][0-9]{1,2})?" required value={amount} onChange={e=>invalidate(setAmount)(normalizeDigits(e.target.value))} placeholder="400"/></label><label>{t('Pay period','मजदूरी की अवधि')}<select required value={period} onChange={e=>invalidate(setPeriod)(e.target.value)}><option value="" disabled>{t('Choose a pay period','अवधि चुनें')}</option><option value="daily">{t('Per day','प्रतिदिन')}</option><option value="weekly">{t('Per week (6 days)','प्रति सप्ताह (6 दिन)')}</option><option value="monthly">{t('Per full month','पूरे महीने की')}</option></select></label></div><Button type="submit" className="full" disabled={busy}>{busy?t('Checking your pay…','मजदूरी जाँच रहा हूँ…'):t('Check my pay','मेरी मजदूरी जाँचें')}<ShieldCheck size={17}/></Button></form><Note>{t('26 paid days per month; 6 per week. Overtime, deductions and partial months require individual review.','माह में 26 और सप्ताह में 6 कार्यदिवस। ओवरटाइम, कटौती और अधूरे माह की अलग समीक्षा जरूरी है।')}</Note><ErrorMessage message={error}/>{result&&<div className="input-context"><Note>{t('This is a provisional benchmark, not a verified legal ruling. A person must verify the latest notification and your circumstances.','यह अस्थायी मानक है, कानूनी निर्णय नहीं। लागू नई अधिसूचना और आपकी स्थिति की किसी व्यक्ति से पुष्टि कराएँ।')}</Note><Source source={result.source}/></div>}</section><section className={`panel result-panel ${result?'result-enter':''} ${result?.status==='underpaid'?'attention-once':''}`} aria-live="polite">{!result?<Empty busy={busy} message={t('I’ll show every number behind your result. Enter your pay to begin.','नतीजे की हर गणना दिखाऊँगा। अपनी मजदूरी भरकर शुरू करें।')}/>:<><Tag tone={result.status==='underpaid'?'amber':'green'}>{t('BENCHMARK COMPARISON','मजदूरी मानक से तुलना')}</Tag><div className="verdict-head"><div><h2>{result.status==='underpaid'?t('Below the benchmark','मानक से कम'):result.status==='fair'?t('At the benchmark','मानक के बराबर'):result.status==='above_minimum'?t('Above the benchmark','मानक से अधिक'):t('Rate unavailable','दर उपलब्ध नहीं')}</h2><p>{t('A clear comparison, with a human next step.','स्पष्ट तुलना, और अगले कदम पर इंसानी सहायता।')}</p></div><Saathi pose={result.status==='underpaid'?'concerned':result.available?'celebrating':'thinking'}/></div>{result.available&&<><div className="verdict-stats"><div><span>{t('Supplied monthly benchmark','दिया गया मासिक मानक')}</span><strong><AnimatedMoney value={result.legal_minimum}/></strong></div><div><span>{t('Your monthly equivalent','आपकी मासिक समतुल्य मजदूरी')}</span><strong><AnimatedMoney value={result.actual_wage_monthly_equivalent}/></strong></div></div>{result.gap>0&&<div className="gap"><span>{t('Monthly difference','मासिक अंतर')}</span><strong><AnimatedMoney value={result.gap}/></strong></div>}</>}<p className="spoken-text">{result.spoken_response_text}</p><Speak text={result.spoken_response_text}/>{result.status==='underpaid'&&<Button className="full" onClick={()=>navigate('/escalate',{state:{verdict:result}})}>{t('Prepare a review case','समीक्षा के लिए मामला तैयार करें')}<ArrowRight size={17}/></Button>}</>}</section></div></>;
}
function Planner(){
 const {t}=useLang();const params=new URLSearchParams(useLocation().search);
 const [city,setCity]=useState(journeyCities.includes(params.get('city'))?params.get('city'):'Noida'),[origin,setOrigin]=useState('Patna'),[job,setJob]=useState('unskilled'),[result,setResult]=useState(null),[mapResult,setMapResult]=useState(null);const {busy,error,run}=useTask();
 const change=setter=>value=>{setter(value);setResult(null);setMapResult(null);};
 const submit=e=>{e.preventDefault();run(async()=>{const r=await api(`route-planner?origin=${origin}&destination=${city}&job_category=${job}`);if(city!=='Patna')await logSearch(r.destination);setResult(r);});};
 const mapLabels={km:t('km'),zoomIn:t('Zoom in'),zoomOut:t('Zoom out'),title:t('Your route map'),loading:t('Finding the road route…'),unavailable:t('The road route could not load. The dotted line only joins the cities.'),road:t('Road route for a car. Check your bus or train separately.'),saved:t('Saved road route. No live traffic information.'),preview:t('Choose your cities, then show your journey.'),retry:t('Try again'),internet:t('The map needs internet. Check your connection and try again.')};
 return <><PageHeading city={city} eyebrow={t('03 / YOUR NEXT MOVE')} title={t('A plan for the road ahead.')} description={t('Choose where you start and where you want to go.')}/><div className="tool-grid route-tool-grid"><section className="panel"><div className="panel-title"><RouteIcon size={21}/><h3>{t('Plan your journey')}</h3></div><form onSubmit={submit}><label>{t('Starting from')}<select data-testid="origin-select" value={origin} onChange={e=>change(setOrigin)(e.target.value)}>{journeyCities.map(c=><option key={c} value={c}>{t(c)}</option>)}</select></label><label>{t('Destination city')}<select data-testid="destination-select" value={city} onChange={e=>change(setCity)(e.target.value)}>{journeyCities.map(c=><option key={c} value={c}>{t(c)}</option>)}</select></label><JobSelect value={job} onChange={change(setJob)}/><Button className="full" disabled={busy}>{busy?t('Planning…'):t('Build my journey plan')}<ArrowRight size={17}/></Button></form><Note>{t('Road routes join city centres. Check your exact address and ticket before travelling.')}</Note><ErrorMessage message={error}/><CityIllustration city={city} label={t(city)} className="route-destination-art"/>{result&&<div className="input-context">{result.expected_wage.available?<div className="route-income"><div className="cost-grid"><div><span>{t('Monthly wage benchmark')}</span><strong>{money(result.expected_wage.monthly)}</strong></div><div><span>{t('Savings after rent & food')} <Tag>{t('estimate')}</Tag></span><strong>{money(result.expected_wage.estimated_monthly_savings_range?.[0])}</strong></div></div><Source source={result.expected_wage.source}/></div>:<Note>{t('Rate unavailable')}</Note>}</div>}</section><section className="panel result-panel" aria-live="polite"><RouteMap origin={origin} destination={city} active={true} onRoute={setMapResult} originLabel={t(origin)} destinationLabel={t(city)} labels={mapLabels}/>{!result?(busy?<Skeleton/>:null):<><div className="route-visual"><span><MapPin size={20}/>{t(result.origin)}</span><div className="route-dots"><ArrowRight size={20}/></div><span><Building2 size={20}/>{t(result.destination)}</span></div>{origin===city&&<Note>{t('You have chosen the same city. No journey between cities is needed.')}</Note>}{result.survival_essentials&&<div className="route-arrival"><h3>{t('Your first stops on arrival')}</h3><div className="essential-row"><Building2 size={18}/><div><strong>{t('Labour office')}</strong><p>{t(result.survival_essentials.labour_office.name)}</p></div></div><div className="essential-row"><HeartPulse size={18}/><div><strong>{t('Government hospital')}</strong><p>{t(result.survival_essentials.government_hospital)}</p></div></div><Link className="btn-glass full" to={`/guide?city=${result.destination}`}>{t('Open city essentials')}<ArrowRight size={17}/></Link></div>}<div className="essential-row"><Phone size={18}/><div><strong>{t('Emergency support')}</strong><a href="tel:112">112</a></div></div></>}</section></div></>;
}
function Guide(){const {t,hi,language,message}=useLang();const params=new URLSearchParams(useLocation().search);const [city,setCity]=useState(cities.includes(params.get('city'))?params.get('city'):'Noida'),[result,setResult]=useState(null),[checked,setChecked]=useState({});const [guideSection,setGuideSection]=useState(0);const {busy,error,run}=useTask();const submit=e=>{e.preventDefault();run(async()=>{const r=await api(`survival-guide?city=${city}`);await logSearch(r.city);setResult(r);setChecked({});});};return <><PageHeading city={city} eyebrow={t('04 / ARRIVE WITH CONFIDENCE','04 / विश्वास के साथ नई शुरुआत')} title={t('A new city. A familiar companion.','नया शहर। अपना साथी।')} description={t('Keep essential support, documents and useful phrases close at hand.','ज़रूरी सहायता, दस्तावेज़ और स्थानीय भाषा की जानकारी अपने पास रखें।')}/><form className="guide-toolbar panel" onSubmit={submit}><CitySelect value={city} onChange={v=>{setCity(v);setResult(null);}}/><Button disabled={busy}>{busy?t('Finding essentials…','जानकारी खोज रहा हूँ…'):t('Show city essentials','शहर की ज़रूरी जानकारी दिखाएँ')}<ArrowRight size={17}/></Button></form><ErrorMessage message={error}/>{!result?<section className="arrival-welcome"><Empty busy={busy} message={t('Pick your city to find support for your first days there.','शहर चुनें और शुरुआती दिनों की सहायता खोजें।')}/></section>:<><div className="row-between guide-title"><h2>{t('Your essentials in','आपकी ज़रूरी जानकारी:')} {t(result.city)}</h2><Speak text={message('guide_message',{city:t(result.city),office:t(result.labour_office.name),hospital:t(result.government_hospital)})}/></div><div className="arrival-tabs" role="tablist" aria-label={t('City essentials')}>{['Help when you need it','A place to stay','Get your documents in order','A few words go a long way'].map((label,i)=><button key={label} id={`arrival-tab-${i}`} role="tab" aria-selected={guideSection===i} aria-controls={`arrival-panel-${i}`} tabIndex={guideSection===i?0:-1} onClick={()=>setGuideSection(i)} onKeyDown={e=>{if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?3:(i+(e.key==='ArrowRight'?1:3))%4;setGuideSection(next);e.currentTarget.parentElement.children[next].focus();}}}>{[<HeartPulse size={19}/>,<HomeIcon size={19}/>,<FileCheck size={19}/>,<Languages size={19}/>][i]}<span>{t(label)}</span></button>)}</div><div className="guide-grid"><aside className="panel arrival-city-card"><CityIllustration city={result.city} label={t(result.city)}/><h3>{t('Your essentials in')} {t(result.city)}</h3><p>{t('Keep essential support, documents and useful phrases close at hand.')}</p></aside><section className="panel arrival-content" id="arrival-panel-0" role="tabpanel" aria-labelledby="arrival-tab-0" hidden={guideSection!==0}><div className="panel-title"><HeartPulse size={22}/><h3>{t('Help when you need it','ज़रूरत पर सहायता')}</h3></div><div className="essential-row"><Building2 size={18}/><div><strong>{t(result.labour_office.name)}</strong><p>{t('Verify address & office hours before visiting.','जाने से पहले पता और समय जाँचें।')}</p><a className="btn-primary guide-link" target="_blank" rel="noreferrer" href={result.labour_office.url}>{t('Labour office')}<ExternalLink size={16}/></a></div></div><div className="essential-row"><HeartPulse size={18}/><div><strong>{t(result.government_hospital)}</strong><p>{t('Confirm address and available services locally.','पते और सेवाओं की स्थानीय पुष्टि करें।')}</p></div></div><div className="contact-strip"><a className="btn-primary guide-link" href="tel:112"><Phone size={16}/>{t('Emergency','आपातकाल')} <b>112</b></a>{result.worker_helpline?<a className="btn-primary guide-link" href={`tel:${result.worker_helpline}`}>{t('Labour office','श्रम कार्यालय')} <b>{result.worker_helpline}</b></a>:<span>{t('Local labour helpline: verify on portal','स्थानीय श्रम हेल्पलाइन: वेबसाइट पर जाँचें')}</span>}</div><div className="guide-source-links"><a className="btn-primary guide-link" href={result.emergency_source} target="_blank" rel="noreferrer">{t('112 official source','112 आधिकारिक स्रोत')}<ExternalLink size={12}/></a>{result.helpline_source&&<a className="btn-primary guide-link" href={result.helpline_source} target="_blank" rel="noreferrer">{t('Labour contact source','श्रम संपर्क स्रोत')}<ExternalLink size={12}/></a>}</div></section><section className="panel arrival-content" id="arrival-panel-1" role="tabpanel" aria-labelledby="arrival-tab-1" hidden={guideSection!==1}><div className="panel-title"><HomeIcon size={22}/><h3>{t('A place to stay','रहने की जगह')}</h3><Tag>{t('general guidance','सामान्य मार्गदर्शन')}</Tag></div><ul className="clean-list">{result.housing.map(x=><li key={x}><CheckCircle2 size={17}/>{t(x)}</li>)}</ul><Note>{t('These are typical options, not verified housing listings or availability.','ये सामान्य विकल्प हैं, सत्यापित मकान या उपलब्धता की सूची नहीं।')}</Note></section><section className="panel arrival-content" id="arrival-panel-2" role="tabpanel" aria-labelledby="arrival-tab-2" hidden={guideSection!==2}><div className="panel-title"><FileCheck size={22}/><h3>{t('Get your documents in order','अपने दस्तावेज़ तैयार करें')}</h3></div><div className="document-links">{result.documentation.map((d,i)=><a className="btn-primary guide-link" key={d.name} target="_blank" rel="noreferrer" href={d.url}><span>{t(d.name)}</span><ExternalLink size={17}/></a>)}</div><p className="muted small">{t('Use official portals. Never share OTPs or pay unofficial registration agents.','आधिकारिक वेबसाइट का उपयोग करें। OTP न दें और अनधिकृत एजेंट को पैसे न दें।')}</p></section><section className="panel arrival-content" id="arrival-panel-3" role="tabpanel" aria-labelledby="arrival-tab-3" hidden={guideSection!==3}><div className="panel-title"><Languages size={22}/><h3>{t('A few words go a long way','कुछ शब्द बड़ा साथ देते हैं')}</h3></div>{result.useful_phrases.map(p=><div className="phrase" key={p.local}><strong>{p.local}</strong><p>{t(p.meaning)}</p><Speak text={p.local} locale={result.city==='Chennai'&&p.local.includes('எ')?'ta-IN':result.city==='Mumbai'?'mr-IN':'hi-IN'}/></div>)}</section></div><section className="panel arrival"><div><span className="eyebrow">{t('BEFORE YOUR FIRST DAY','पहले कार्यदिवस से पहले')}</span><h3>{t('Your arrival checklist','पहुँचने की चेकलिस्ट')}</h3></div><div>{result.checklist.map((c,i)=><label className="check-row" key={i}><input type="checkbox" checked={!!checked[i]} onChange={e=>setChecked({...checked,[i]:e.target.checked})}/><span>{t(c)}</span></label>)}</div></section></>}</>;}
function CityDetails({selected,onClose,returnFocus}){
 const {t}=useLang();const dialog=useRef(null);const record=selected.worker_record;
 const close=()=>{dialog.current.close();onClose();returnFocus?.focus();};
 useEffect(()=>{const node=dialog.current;node.showModal();return()=>node.close();},[]);
 return <dialog ref={dialog} className="city-details-dialog" aria-labelledby="selected-city-title" onCancel={e=>{e.preventDefault();close();}} onClick={e=>{if(e.target===dialog.current)close();}}><section className="panel city-detail-panel" aria-labelledby="selected-city-title"><div className="city-detail-title"><div className="selected-city-heading"><span className="feature-icon"><MapPin size={20}/></span><div><h3 id="selected-city-title">{t(selected.city)}</h3><p>{t(selected.state)}</p></div></div><button className="icon-button" aria-label={t('Close city details')} onClick={close} autoFocus><X size={18}/></button></div><div className="city-detail-money"><div><span>{t('Monthly wage benchmark')}</span><strong>{money(selected.avg_wage)}</strong></div><div><span>{t('RENT + FOOD')}</span><strong>{money(selected.typical_rent+selected.typical_food)}</strong></div><div className="detail-savings"><span>{t('Savings potential')} <Tag>{t('estimate')}</Tag></span><strong>{money(selected.estimated_monthly_savings_range[0])}</strong></div></div><div className="city-next-actions"><Link className="city-step city-step-primary" to={`/predict?city=${selected.city}`}><Wallet size={21}/><div><strong>{t('Wage outlook')}</strong><span>{t('Know what your work is worth.')}</span></div><ArrowRight size={17}/></Link><Link className="city-step" to={`/route?city=${selected.city}`}><RouteIcon size={21}/><div><strong>{t('Plan your route')}</strong><span>{t('A plan for the road ahead.')}</span></div><ArrowRight size={17}/></Link><Link className="city-step" to={`/guide?city=${selected.city}`}><BookOpen size={21}/><div><strong>{t('City essentials')}</strong><span>{t('Keep essential support, documents and useful phrases close at hand.')}</span></div><ArrowRight size={17}/></Link></div><div className="city-detail-grid"><div className="city-pay-source"><Source source={selected.source}/></div><details className="city-worker-record"><summary><Building2 size={17}/><div><strong>{t('WELFARE REGISTRATION')}</strong><span>{t('State-wide record')}</span></div><strong className="worker-count">{(record?.figure??selected.bocw.figure)?.toLocaleString('en-IN')||t('Not publicly available')}</strong><ChevronDown size={16}/></summary><div className="record-content"><p>{record?t(record.label):t(selected.bocw.metric_type?.replaceAll('_',' ')||'Registration data not publicly available in the supplied dataset.')}</p><p>{t(record?.state||selected.bocw.state)} · {record?.period||selected.bocw.as_of_date}</p><p className="small">{t('These figures cover the whole state, not this city. They do not show whether an employer is safe.')}</p><a className="text-link small" target="_blank" rel="noreferrer" href={record?.source_url||selected.bocw.source_url}>{t('Official portal')}<ExternalLink size={13}/></a></div></details></div></section></dialog>;
}
function Opportunities(){
 const {t}=useLang();const [rows,setRows]=useState(null),[sort,setSort]=useState('city'),[selected,setSelected]=useState(null),[detailsOpen,setDetailsOpen]=useState(false);const detailsTrigger=useRef(null);const {busy,error,run}=useTask();
 useEffect(()=>{run(async()=>{const data=await api('opportunity-map');setRows(data);setSelected(data.find(r=>r.city==='Chennai'));});},[]);
 const sorted=rows?[...rows].sort((a,b)=>sort==='city'?a.city.localeCompare(b.city):sort==='cost'?a.cost_of_living_index-b.cost_of_living_index:sort==='wage'?b.avg_wage-a.avg_wage:b.estimated_monthly_savings_range[0]-a.estimated_monthly_savings_range[0]):[];
 const select=(r,trigger)=>{detailsTrigger.current=trigger;setSelected(r);setDetailsOpen(true);run(async()=>{await logSearch(r.city);});};
 return <><PageHeading city={selected?.city||'Chennai'} eyebrow={t('02 / EXPLORE YOUR OPTIONS')} title={t('Different cities. A clearer choice.')} description={t('Compare the basics side by side. Choose what matters to you, with every caveat in view.')}/><ErrorMessage message={error}/><div className="cities-workspace"><div className="city-card-toolbar"><span>{t('5 cities · select a row for sources')}</span><label>{t('Sort by')}<select value={sort} onChange={e=>setSort(e.target.value)}><option value="city">{t('City name')}</option><option value="savings">{t('Savings potential')}</option><option value="wage">{t('Wage benchmark')}</option><option value="cost">{t('Living costs')}</option></select></label></div>{!rows?<section className="panel"><Empty busy={busy} message={t('Gathering the five-city comparison.')}/></section>:<><section className="city-choice-grid" aria-label={t('Choose a city')}>{sorted.map(r=><article className={`city-choice panel ${selected?.city===r.city?'is-selected':''}`} key={r.city} data-city={r.city}><div className="city-choice-heading"><span className="feature-icon"><MapPin size={22}/></span><div><h2>{t(r.city)}</h2><p>{t(r.state)}</p></div></div><div className="city-pay"><span>{t('Monthly wage benchmark')}</span><strong>{money(r.avg_wage)}</strong></div><div className="city-costs"><div><span>{t('Shared rent')}</span><strong>{money(r.typical_rent)}</strong></div><div><span>{t('Food')}</span><strong>{money(r.typical_food)}</strong></div></div><div className="city-savings"><span>{t('Savings potential')} <Tag>{t('estimate')}</Tag></span><strong>{money(r.estimated_monthly_savings_range[0])}</strong></div><Button secondary={selected?.city!==r.city} className="full" aria-pressed={selected?.city===r.city} onClick={e=>select(r,e.currentTarget)}>{t('DETAILS')}<ArrowRight size={16}/></Button></article>)}</section><Note>{t('Transparent by design: wage benchmarks need notification verification; living costs and travel distances are planning estimates.')}</Note>{detailsOpen&&selected&&<CityDetails selected={selected} returnFocus={detailsTrigger.current} onClose={()=>setDetailsOpen(false)}/>}</>}</div></>;
}
function Escalation(){const {t}=useLang();const location=useLocation();const v=location.state?.verdict;const [consent,setConsent]=useState(false),[result,setResult]=useState(null);const {busy,error,run}=useTask();if(!v)return <><PageHeading city={v?.city||"Noida"} eyebrow={t('06 / HUMAN REVIEW','06 / इंसानी समीक्षा')} title={t('Start with a wage check.','पहले मजदूरी जाँचें।')} description={t('A review case needs the result of your wage comparison.','समीक्षा के मामले के लिए मजदूरी की तुलना का नतीजा चाहिए।')}/><section className="panel"><Empty message={t('Check your pay first. If it is below the supplied benchmark, you can prepare a case here.','पहले मजदूरी जाँचें। मानक से कम होने पर यहाँ मामला तैयार कर सकते हैं।')}/><Link className="btn-primary" to="/check">{t('Check my pay','मेरी मजदूरी जाँचें')}<ArrowRight size={17}/></Link></section></>;return <><PageHeading city={v?.city||"Noida"} eyebrow={t('06 / YOUR CHOICE, ALWAYS','06 / चुनाव हमेशा आपका')} title={t('Your voice. A human next step.','आपकी आवाज़। अगला कदम इंसान के साथ।')} description={t('Prepare an anonymous case for review. Nothing is sent to an external organisation.','समीक्षा के लिए गुमनाम मामला तैयार करें। किसी बाहरी संस्था को नहीं भेजा जाएगा।')}/><div className="tool-grid"><section className="panel"><Saathi pose="reassuring" message={t('I’ll only prepare this if you tell me to. A real person must review it before any action.','आपकी अनुमति पर ही मामला तैयार करूँगा। किसी कदम से पहले असली व्यक्ति की समीक्षा जरूरी है।')}/><div className="verdict-stats"><div><span>{t('Monthly benchmark','मासिक मानक')}</span><strong>{money(v.legal_minimum)}</strong></div><div><span>{t('Monthly difference','मासिक अंतर')}</span><strong>{money(v.gap)}</strong></div></div><Note>{t('Demo delivery only: saved on this app’s server. No real NGO connection or reviewer is assigned. This provisional comparison must be verified before real submission.','केवल डेमो: इस ऐप के सर्वर पर सुरक्षित होगा। कोई वास्तविक NGO कनेक्शन या समीक्षक नहीं है। असली आवेदन से पहले इस तुलना की पुष्टि जरूरी है।')}</Note><label className="check-row consent"><input type="checkbox" checked={consent} onChange={e=>setConsent(e.target.checked)} disabled={!!result}/><span>{t('I consent to creating a local, anonymous case file. I understand that no external report will be sent.','मैं स्थानीय, गुमनाम मामला बनाने की अनुमति देता हूँ। मैं समझता हूँ कि बाहरी रिपोर्ट नहीं भेजी जाएगी।')}</span></label><Button className="full" disabled={!consent||busy||!!result} onClick={()=>run(async()=>setResult(await api('escalate',{verdict_id:v.verdict_id,consent:true})))}>{result?t('Case prepared','मामला तैयार'):busy?t('Preparing…','तैयार कर रहा हूँ…'):t('Prepare my review case','मेरा समीक्षा मामला तैयार करें')}<FileCheck size={17}/></Button><ErrorMessage message={error}/></section><section className="panel result-panel" aria-live="polite">{!result?<Empty message={t('Your case file will appear here only after you give consent.','आपकी अनुमति के बाद ही मामला यहाँ दिखेगा।')}/>:<><Tag tone="green"><Check size={14}/>{t('SAVED LOCALLY · MOCK DELIVERY','स्थानीय सेव · डेमो डिलीवरी')}</Tag><h2>{t('Your case is ready to review.','आपका मामला समीक्षा के लिए तैयार है।')}</h2><p className="muted">{t('No external organisation has received it. Download a copy for a trusted person to review.','किसी बाहरी संस्था को नहीं भेजा गया। भरोसेमंद व्यक्ति की समीक्षा के लिए प्रति डाउनलोड करें।')}</p><div className="verdict-stats"><div><span>{t('Pay received (₹)')}</span><strong>{money(result.case_file.verdict.actual_wage_monthly_equivalent)}</strong></div><div><span>{t('Monthly difference')}</span><strong>{money(result.case_file.verdict.gap)}</strong></div></div><Button onClick={()=>downloadJSON(result.case_file,`saathi-case-${result.case_file.case_id}.json`)}><Download size={17}/>{t('Download case file','मामला डाउनलोड करें')}</Button><Note>{t('Human review required. Keep your copy private. There is no automatic dispute resolution.','इंसानी समीक्षा जरूरी है। अपनी प्रति निजी रखें। विवाद अपने आप हल नहीं होगा।')}</Note></>}</section></div></>;}
class ErrorBoundary extends React.Component {constructor(props){super(props);this.state={failed:false};}static getDerivedStateFromError(){return{failed:true};}render(){return this.state.failed?<div className="empty"><h1>{translate(languageInfo(localStorage.getItem('saathi-language')).code,'Try again')}</h1><p>{translate(languageInfo(localStorage.getItem('saathi-language')).code,'Please refresh to try again.')}</p><button className="btn-primary" onClick={()=>window.location.reload()}>{translate(languageInfo(localStorage.getItem('saathi-language')).code,'Refresh')}</button></div>:this.props.children;}}
createRoot(document.getElementById('root')).render(<ErrorBoundary><BrowserRouter><App/></BrowserRouter></ErrorBoundary>);
